function toast(message,error){var el=$('#toast');el.textContent=message;el.className=error?'error':'';el.hidden=false;clearTimeout(el._timer);el._timer=setTimeout(function(){el.hidden=true},error?10000:4000);}
async function api(path,body){var opts={credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF':csrf}};if(body!==undefined){opts.method='POST';opts.body=JSON.stringify(body)}var response=await fetch('/api/'+path,opts),data=await response.json();if(!response.ok){if(response.status===401){state=null;stopAttempt();loginPage()}var failure=Error(data.error||'Ошибка сервера');failure.status=response.status;throw failure}return data;}
async function run(fn){try{await fn()}catch(e){toast(e.message,true)}}
async function reload(){state=await api('state');csrf=state.csrf;serverOffset=state.serverTime-Date.now();if(state.user.language){lang=state.user.language;localStorage.setItem('edutest-language',lang)}}
function av(u,big){return u.avatar?'<img class="avatar '+(big?'big':'')+'" alt="" src="'+esc(u.avatar)+'">':'<span class="avatar '+(big?'big':'')+'">'+esc((u.name||'?').split(' ').slice(0,2).map(function(x){return x[0]}).join(''))+'</span>'}
function shortName(value){var name=typeof value==='string'?value:(value&&value.name)||'';return String(name).trim().split(/\s+/).filter(Boolean).slice(0,2).join(' ')||'?'}
function btn(label,action,primary,data){return '<button type="button" '+(action?'data-action="'+action+'"':'')+' '+(data!==undefined&&data!==null?'data-id="'+esc(data)+'"':'')+' class="'+(primary?'primary':'')+'">'+esc(t(label))+'</button>'}
function inp(label,id,value,type){return '<label for="'+id+'">'+esc(t(label))+'</label><input id="'+id+'" type="'+(type||'text')+'" value="'+esc(value||'')+'">'}
function select(label,id,values,value,multiple){return '<label for="'+id+'">'+esc(t(label))+'</label><select id="'+id+'" '+(multiple?'multiple':'')+'>'+values.map(function(v){var val=Array.isArray(v)?v[0]:v,label=Array.isArray(v)?v[1]:t(v);return '<option value="'+esc(val)+'" '+((multiple?(value||[]).indexOf(val)>=0:val===value)?'selected':'')+'>'+esc(label)+'</option>'}).join('')+'</select>'}
function ta(label,id,value,code){return '<label for="'+id+'">'+esc(t(label))+'</label><textarea id="'+id+'" '+(code?'class="code" spellcheck="false"':'')+'>'+esc(value||'')+'</textarea>'}
function title(name,desc){return '<div class="eyebrow">ZERDE AI</div><h1>'+esc(t(name))+'</h1>'+(desc?'<p class="muted">'+esc(t(desc))+'</p>':'')}
function languageSelect(){return '<select id="uiLang" aria-label="Язык"><option value="ru" '+(lang==='ru'?'selected':'')+'>Русский</option><option value="kk" '+(lang==='kk'?'selected':'')+'>Қазақша</option></select>'}
function loginPage(){stopAttempt();$('#app').innerHTML='<div class="login"><div class="intro"><div class="eyebrow">ZERDE AI / JAVA</div><h1>'+t('Изучайте. Практикуйтесь. Развивайтесь.')+'</h1><p class="muted">'+t('Одна база для приложения и телефона.')+'</p></div><form id="loginForm" class="card"><div class="row between"><div class="brand">Zerde <span>AI</span></div>'+languageSelect()+'</div><h2>'+t('Вход в аккаунт')+'</h2><p class="muted small">'+t('Выберите роль и введите данные, выданные преподавателем.')+'</p><div class="role"><button type="button" data-action="roleStudent" class="'+(role==='student'?'selected':'')+'">'+t('Студент')+'</button><button type="button" data-action="roleTeacher" class="'+(role==='teacher'?'selected':'')+'">'+t('Преподаватель')+'</button></div>'+inp('Фамилия для входа','loginName','','text')+inp('Пароль','loginPass','','password')+'<button type="submit" class="primary">'+t('Войти')+'</button><p class="muted small"><a href="http://localhost:8082/" target="_blank" rel="noopener">'+t('Вход администратора')+'</a></p><p class="muted small">'+t('Аккаунт студента создаёт преподаватель.')+'</p></form></div>';$('#loginName').required=true;$('#loginPass').required=true;$('#loginForm').onsubmit=function(e){e.preventDefault();var button=this.querySelector('[type=submit]');button.disabled=true;run(async function(){try{var r=await api('login',{role:role,login:$('#loginName').value,password:$('#loginPass').value});csrf=r.csrf;await reload();show('home')}finally{button.disabled=false}})};bindLang()}
var routes={progress:'Прогресс',home:'Обзор',tasks:'Задания',archive:'Архив',trash:'Корзина',create:'Создать задание',students:'Студенты',groups:'Группы',materials:'Материалы',results:'Результаты',ai:'Настройки ИИ',profile:'Профиль',online:'Сайт онлайн',backup:'Резервные копии',help:'Справка'};
function shell(){var teacher=state.user.role==='teacher',names=teacher?['home','tasks','archive','trash','create','materials','groups','students','results','progress','ai','profile','backup','help']:['home','tasks','results','progress','profile','help'];if(teacher&&hasOnlineSite())names.splice(names.indexOf('ai'),0,'online');$('#app').innerHTML='<aside class="aside"><div class="brand">Zerde <span>AI</span></div><span class="eyebrow">'+t(teacher?'Преподаватель':'Студент')+'</span><nav>'+names.map(function(k){return '<button data-route="'+k+'" class="'+(screen===k?'active':'')+'">'+t(routes[k])+'</button>'}).join('')+'</nav><footer><div class="profile-line">'+av(state.user)+'<span>'+esc(shortName(state.user))+'</span></div><p>'+btn('Выйти','logout')+'</p></footer></aside><main class="main"><header class="top"><button class="menu" data-action="menu" aria-label="Меню">☰</button><span class="small muted">'+t('Рабочее пространство')+' / '+t(routes[screen]||'Задания')+'</span>'+languageSelect()+'</header><section class="content" id="content"></section></main>';bindLang()}
function bindLang(){$('#uiLang').onchange=function(){lang=this.value;localStorage.setItem('edutest-language',lang);if(state){run(async function(){await api('profile',{language:lang});state.user.language=lang;if(screen==='editor'){editor(collectDraft())}else if(screen==='attempt'&&attempt){await queueSave();exam(await api('attempt/get',{id:attempt.id}))}else if(screen==='result'){show('results')}else{show(screen)}})}else loginPage()}}
function stopAttempt(){clearInterval(timer);clearInterval(saveTimer);timer=null;saveTimer=null;attempt=null;}
function show(page){clearTimeout(onlineTimer);if(attempt&&page!=='attempt'){stopAttempt()}screen=page;shell();var f={home:homePage,tasks:tasksPage,archive:tasksPage,trash:tasksPage,create:createPage,students:studentsPage,groups:groupsPage,materials:materialsPage,results:resultsPage,progress:progressPage,ai:aiPage,profile:profilePage,online:onlinePage,backup:backupPage,help:helpPage}[page];if(f)f()}
function homePage(){var done=state.results.filter(function(r){return r.status==='submitted'}),average=done.length?Math.round(done.reduce(function(sum,r){return sum+r.score/r.total*100},0)/done.length):0,teacher=state.user.role==='teacher';$('#content').innerHTML=title('Добро пожаловать')+'<p class="muted">'+esc(shortName(state.user))+'</p><div class="hero"><div class="eyebrow">JAVA · PDF / WORD · AI</div><h1>'+t(teacher?'Создавайте задания. Помогайте понимать.':'Изучайте. Практикуйтесь. Развивайтесь.')+'</h1><p>'+t('Одна база для приложения и телефона.')+'</p><button class="primary" data-route="'+(teacher?'create':'tasks')+'">'+t(teacher?'Создать задание':'Открыть задания')+' →</button></div><div class="grid">'+[['Заданий',state.tasks.filter(function(x){return !x.trashed&&(!x.published||x.active)}).length],['Завершённых попыток',done.length],['Средний результат',average+'%']].map(function(a){return '<div class="card"><span class="muted">'+t(a[0])+'</span><div class="number">'+a[1]+'</div></div>'}).join('')+'</div><div class="card"><h3>'+t('Материалы')+' → '+t('Задания')+' → '+t('Результаты')+'</h3><p class="muted">'+(lang==='kk'?'Материалды жүктеңіз, тапсырмаларды тексеріп жариялаңыз. Студенттер оларды қосымшада немесе телефонда орындайды.':'Загрузите материал, проверьте задания и опубликуйте. Студенты выполнят их в приложении или на телефоне.')+'</p></div>'}
function groupsPage(){ $('#content').innerHTML=title('Группы')+'<form id="groupForm" class="card">'+inp('Название группы','groupName','')+'<div class="form-actions"><button class="primary">'+t('Добавить группу')+'</button></div></form><div class="grid">'+state.groups.map(function(g){return '<div class="card"><h3>'+esc(g.name)+'</h3><p class="muted">'+state.users.filter(function(u){return u.group===g.id}).length+' · '+t('Студенты')+'</p>'+btn('Редактировать','editGroup',false,g.id)+'</div>'}).join('')+'</div>';$('#groupForm').onsubmit=function(e){e.preventDefault();run(async function(){await api('groups/save',{name:$('#groupName').value});await reload();show('groups')})}}
function studentsPage(){ $('#content').innerHTML=title('Студенты')+'<div class="row between">'+btn('Добавить студента','newStudent',true)+'<input id="userSearch" placeholder="'+t('Поиск')+'" style="max-width:320px"></div><div id="userForm"></div><div class="card scroll table-card"><table><thead><tr><th>'+t('Полное ФИО')+'</th><th>'+t('Логин')+'</th><th>'+t('Группа')+'</th><th>'+t('Действия')+'</th></tr></thead><tbody id="userRows"></tbody></table></div>';var render=function(){var query=$('#userSearch').value.toLowerCase();$('#userRows').innerHTML=state.users.filter(function(u){return (u.name+' '+u.login).toLowerCase().indexOf(query)>=0}).map(function(u){var g=state.groups.find(function(g){return g.id===u.group});return '<tr><td><div class="profile-line">'+av(u)+'<span>'+esc(u.name)+'</span></div></td><td>'+esc(u.login)+'</td><td>'+esc(g?g.name:t('Без группы'))+'</td><td>'+btn('Редактировать','editStudent',false,u.id)+'</td></tr>'}).join('')};$('#userSearch').oninput=render;render()}
function editStudent(uid){var u=state.users.find(function(x){return x.id===uid})||{name:'',login:'',group:'',active:true};$('#userForm').innerHTML='<form id="studentForm" class="card"><h2>'+t(uid?'Редактировать':'Добавить студента')+'</h2><div class="two"><div>'+inp('Фамилия для входа','studentLogin',u.login)+'</div><div>'+inp('Имя, фамилия, отчество','studentName',u.name)+'</div><div>'+inp(uid?'Новый пароль':'Пароль','studentPassword','','password')+'</div><div>'+select('Группа','studentGroup',[['',t('Без группы')]].concat(state.groups.map(function(g){return [g.id,g.name]})),u.group)+'</div></div><label class="check"><input id="studentActive" type="checkbox" '+(u.active?'checked':'')+'>'+t('Аккаунт активен')+'</label><p class="muted small">'+(lang==='kk'?'Бірдей тегіне рұқсат етіледі. Тегі мен құпиясөз жұбы қайталанбауы керек.':'Одинаковые фамилии разрешены. Сочетание фамилии и пароля должно отличаться. При редактировании пустой пароль сохраняет прежний.')+'</p><button class="primary">'+t('Сохранить')+'</button></form>';$('#studentForm').onsubmit=function(e){e.preventDefault();run(async function(){await api('users/save',{id:uid||'',login:$('#studentLogin').value,name:$('#studentName').value,password:$('#studentPassword').value,group:$('#studentGroup').value,active:$('#studentActive').checked});await reload();show('students');toast(t('Готово'))})}}
function materialsPage(){ $('#content').innerHTML=title('Библиотека материалов')+'<details class="card"><summary>'+t('Загрузить материал')+'</summary><form id="uploadForm"><div class="two"><div>'+inp('Название','matTitle','')+'</div><div>'+inp('Предмет','matSubject','')+'</div><div>'+inp('Тема','matTopic','')+'</div><div><label>'+t('Файл PDF / Word')+'</label><input id="matFile" type="file" accept=".pdf,.docx,.txt,.md" required></div></div><p class="small muted">PDF / DOCX / TXT · 12 МБ · '+(lang==='kk'?'Сканерленген PDF үшін мәтіндік қабат қажет.':'Для сканированного PDF нужен текстовый слой (OCR).')+'</p><button class="primary">'+t('Загрузить материал')+'</button></form></details><input id="matSearch" placeholder="'+t('Поиск')+'"><div id="materialCards"></div>';var render=function(){var q=$('#matSearch').value.toLowerCase();$('#materialCards').innerHTML=state.materials.filter(function(m){return (m.title+' '+m.subject+' '+m.topic).toLowerCase().indexOf(q)>=0}).map(function(m){return '<div class="card"><span class="tag">'+esc(m.subject)+'</span><h3>'+esc(m.title)+'</h3><p class="muted">'+esc(m.topic)+' · '+esc(m.filename)+'</p><details><summary>'+t('Текст документа')+'</summary><div class="material">'+m.pages.map(function(p){return '<p><b>'+esc(p.ref+' · '+p.label)+'</b></p><pre>'+esc(p.text)+'</pre>'}).join('')+'</div></details><div class="row">'+btn('Использовать для задания','useMaterial',true,m.id)+btn('Скачать оригинал','downloadMaterial',false,m.id)+btn('Редактировать','editMaterial',false,m.id)+'</div></div>'}).join('')};$('#matSearch').oninput=render;render();$('#uploadForm').onsubmit=function(e){e.preventDefault();var f=$('#matFile').files[0],button=this.querySelector('button');if(!f)return;run(async function(){button.disabled=true;try{if(f.size>12000000)throw Error('Максимум 12 МБ');var data=await base64(f);await api('material/upload',{title:$('#matTitle').value,subject:$('#matSubject').value,topic:$('#matTopic').value,filename:f.name,data:data});await reload();show('materials');toast(t('Файл загружен'))}finally{button.disabled=false}})}}
function base64(file){return new Promise(function(resolve,reject){var r=new FileReader();r.onload=function(){resolve(String(r.result).split(',')[1])};r.onerror=reject;r.readAsDataURL(file)})}
function download(name,content,type){var blob=content instanceof Blob?content:new Blob([content],{type:type||'text/plain;charset=utf-8'});if(window.nativeBridge){var reader=new FileReader();reader.onload=function(){window.nativeBridge.save(name,String(reader.result).split(',')[1])};reader.readAsDataURL(blob);return}var url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(url)},30000)}
function emptyTask(){return {id:'',title:'',subject:'Программирование',topic:'',language:'Java',contentLanguage:lang,level:'Лёгкий',type:'quiz',material:'',source:'Преподаватель',settings:{minutes:30,attempts:1,deadline:0,shuffle:true,reveal:'immediate',groups:[],students:[]},body:{questions:[newQuestion()]}}}
