function progressPage(){
 var teacher=state.user.role==='teacher', results=(state.results||[]).slice(),users=teacher?(state.users||[]):[];
 $('#content').innerHTML=title('Прогресс','Динамика обучения по фактически сохранённым попыткам')+
  '<div class="card"><div class="row between"><div><strong>'+t('Мониторинг обучения')+'</strong><p class="muted small">'+t('Данные из общей базы Zerde AI')+'</p></div><button id="progressRefresh" class="primary">'+t('Обновить')+'</button></div><div class="two"><div><label>'+t('Поиск ученика или задания')+'</label><input id="progressFind" placeholder="'+t('Поиск')+'"></div><div><label>'+t('Период')+'</label><select id="progressPeriod"><option value="all">'+t('Всё время')+'</option><option value="7">'+t('7 дней')+'</option><option value="30">'+t('30 дней')+'</option><option value="90">'+t('90 дней')+'</option></select></div></div></div><div id="progressBody"></div>';
 $('#progressRefresh').onclick=function(){run(async function(){await reload();show('progress');toast(t('Данные обновлены'))})};
 $('#progressFind').oninput=paint;$('#progressPeriod').onchange=paint;paint();
 function paint(){
  var q=$('#progressFind').value.trim().toLowerCase(),days=$('#progressPeriod').value,cutoff=days==='all'?0:Date.now()-Number(days)*86400000;
  var rows=results.filter(function(r){return (!cutoff||Number(r.started)>=cutoff)&&(!q||(String(r.student||'')+' '+String(r.title||'')).toLowerCase().includes(q))});
  var done=rows.filter(function(r){return r.status==='submitted'&&Number(r.total)>0&&Number.isFinite(Number(r.score))});
  var avg=done.length?Math.round(done.reduce(function(a,r){return a+Math.max(0,Math.min(100,100*Number(r.score)/Number(r.total)))},0)/done.length):null;
  var active=rows.filter(function(r){return r.status==='active'||r.status==='checking'}).length;
  var cards=[['Попыток',rows.length],['Завершено',done.length],['Средний балл',avg===null?'—':avg+'%'],['В работе',active]];
  var html='<div class="progress-metrics">'+cards.map(function(k){return '<div class="card"><div class="muted small">'+t(k[0])+'</div><div class="number">'+esc(k[1])+'</div></div>'}).join('')+'</div>';
  var daysMap={};done.forEach(function(r){var date=new Date(Number(r.started)).toLocaleDateString(lang==='kk'?'kk-KZ':'ru-RU');(daysMap[date]||(daysMap[date]=[])).push(Math.max(0,Math.min(100,100*Number(r.score)/Number(r.total))))});
  var keys=Object.keys(daysMap).sort(function(a,b){return new Date(a.split('.').reverse().join('-'))-new Date(b.split('.').reverse().join('-'))}).slice(-12);
  html+='<div class="card"><h3>'+t('Динамика результатов')+'</h3>'+(keys.length?'<div class="progress-bars">'+keys.map(function(k){var score=Math.round(daysMap[k].reduce(function(a,b){return a+b},0)/daysMap[k].length);return '<div class="progress-bar-item" title="'+esc(k)+' — '+score+'%"><span>'+score+'%</span><div class="progress-track"><div class="progress-fill" style="height:'+score+'%"></div></div><small>'+esc(k)+'</small></div>'}).join('')+'</div>':'<p class="muted">'+t('Пока нет завершённых попыток за выбранный период.')+'</p>')+'</div>';
  var bySubject={};done.forEach(function(r){var key=String(r.title||'Без названия');(bySubject[key]||(bySubject[key]=[])).push(Math.max(0,Math.min(100,100*Number(r.score)/Number(r.total))))});
  var topics=Object.keys(bySubject).map(function(k){return {name:k,n:bySubject[k].length,percent:Math.round(bySubject[k].reduce(function(a,b){return a+b},0)/bySubject[k].length)}}).sort(function(a,b){return b.n-a.n});
  html+='<div class="card"><h3>'+t('Результаты по заданиям')+'</h3>'+(topics.length?topics.map(function(x){return '<div class="progress-topic"><div class="row between"><strong>'+esc(x.name)+'</strong><span>'+x.percent+'% · '+x.n+'</span></div><div class="progress-line"><div style="width:'+x.percent+'%"></div></div></div>'}).join(''):'<p class="muted">'+t('Нет результатов')+'</p>')+'</div>';
  if(teacher){
   var names={};rows.forEach(function(r){var key=String(r.student||'Неизвестный студент');(names[key]||(names[key]=[])).push(r)});
   var students=Object.keys(names).sort().map(function(k){var rr=names[k],finished=rr.filter(function(r){return r.status==='submitted'&&Number(r.total)>0});var score=finished.length?Math.round(finished.reduce(function(a,r){return a+Math.max(0,Math.min(100,Number(r.score)*100/Number(r.total)))},0)/finished.length):null;return {name:k,attempts:rr.length,finished:finished.length,score:score}});
   html+='<div class="card scroll table-card"><h3>'+t('Прогресс студентов')+'</h3><table><thead><tr><th>'+t('Студент')+'</th><th>'+t('Попыток')+'</th><th>'+t('Завершено')+'</th><th>'+t('Средний балл')+'</th></tr></thead><tbody>'+students.map(function(u){return '<tr><td>'+esc(u.name)+'</td><td>'+u.attempts+'</td><td>'+u.finished+'</td><td>'+(u.score===null?'—':u.score+'%')+'</td></tr>'}).join('')+'</tbody></table>'+(students.length?'':'<p class="muted">'+t('Нет результатов')+'</p>')+'</div>';
  }
  html+='<p class="muted small">'+t('Обновляется при входе в раздел или по кнопке «Обновить». Оценки берутся только из сохранённых результатов.')+'</p>';
  $('#progressBody').innerHTML=html;
 }
}
