  var wrap=document.createElement('section');wrap.className='card za-exam-settings';wrap.style.cssText='margin-top:17px;border:1px solid #26aa98;padding:20px';
  wrap.innerHTML='<h3 style="margin-top:0">Режим проведения</h3><label for="'+prefix+'Mode">Выбор преподавателя</label><select id="'+prefix+'Mode"><option value="normal">Обычный тест</option><option value="strict">Строгий экзамен — Alt + мышь (ПК)</option></select><div id="'+prefix+'Strict" style="margin-top:12px"><p class="muted small">Доступен только для компьютеров с клавиатурой и мышью. Клиентский контроль активности не является надёжной защитой от списывания. У преподавателя пока нет серверного журнала нарушений.</p><label for="'+prefix+'Limit">Число предупреждений</label><input id="'+prefix+'Limit" type="number" min="1" max="10" value="5"><label for="'+prefix+'Action">После превышения лимита</label><select id="'+prefix+'Action"><option value="submit">Завершить и отправить ответы</option><option value="lock">Блокировать попытку (без безопасной разблокировки — только демо)</option></select></div>';
