  host.parentNode.insertBefore(banner,host);
  var limit=Number(settings.examLimit)||5, cnt=0, held=false, moved=Date.now(),startup=Date.now(),lastViolation=0,locked=false,lastIdle=false,everHeld=false,log=[];
  function update(){var st=document.getElementById('za-guard-status'),co=document.getElementById('za-guard-count'),lg=document.getElementById('za-guard-log');if(st)st.textContent=locked?'Экзамен заблокирован':('Alt: '+(held?'удерживается':'отпущен')+' · Мышь: '+(Date.now()-moved<5000?'активна':'нет движения'));if(co)co.textContent='Предупреждения: '+cnt+' / '+limit;if(lg)lg.innerHTML=log.slice(-4).map(function(x){return '<div>'+esc(x)+'</div>'}).join('')}
  function violate(reason){if(locked||Date.now()-startup<5000||Date.now()-lastViolation<1400)return;lastViolation=Date.now();cnt++;log.push(new Date().toLocaleTimeString()+' — '+reason);update();banner.style.borderColor='#dc374f';if(cnt>limit){locked=true;banner.querySelector('h3').textContent='Экзамен остановлен: превышен лимит предупреждений';if(settings.examAction==='submit'){run(function(){return submitExam(false)})}else{host.style.pointerEvents='none';host.style.opacity='.52';var msg=document.createElement('p');msg.textContent='Попытка заблокирована локально. Проверка пароля преподавателя сервером пока не реализована. Обратись к преподавателю для решения вопроса.';banner.appendChild(msg)} }else {var warning=document.createElement('p');warning.style.cssText='color:#e63953;font-weight:700';warning.textContent='Нарушение '+cnt+'/'+limit+': '+reason;banner.appendChild(warning);setTimeout(function(){if(warning.isConnected)warning.remove()},4500)}}
